SELECT analytics_order_facts.category, COUNT(DISTINCT analytics_order_facts.order_id) AS order_count FROM analytics_order_facts WHERE analytics_order_facts.year = 2023 AND analytics_order_facts.month = 10 AND analytics_order_facts.region = 'East' AND analytics_order_facts.channel = 'retail' AND analytics_order_facts.customer_segment = 'small_business' AND analytics_order_facts.category = 'category_11' GROUP BY analytics_order_facts.category ORDER BY order_count DESC, analytics_order_facts.category ASC LIMIT 10
